import java.util.*;
import java.util.function.LongSupplier;

public class Solution {
    enum Nivel { DEBUG, INFO, WARN, ERROR }

    record Evento(long timestampMillis, Nivel nivel, String logger, String mensagem) {}

    interface Formatador {
        String formatar(Evento e);
    }

    interface Appender {
        void escrever(String linha);
    }

    // Pronto: "timestamp NIVEL [logger] mensagem"
    static class FormatadorPadrao implements Formatador {
        @Override
        public String formatar(Evento e) {
            return e.timestampMillis() + " " + e.nivel() + " [" + e.logger() + "] " + e.mensagem();
        }
    }

    // Pronto: guarda as linhas em memória, útil para testes.
    static class MemoriaAppender implements Appender {
        private final List<String> linhas = new ArrayList<>();

        @Override
        public void escrever(String linha) {
            linhas.add(linha);
        }

        List<String> linhas() {
            return List.copyOf(linhas);
        }
    }

    static class LoggerFactory {
        private record Saida(Appender appender, Formatador formatador, Nivel minimo) {}

        private final LongSupplier relogio;
        private final Map<String, Logger> loggers = new HashMap<>();
        private final Map<String, Nivel> niveis = new HashMap<>(Map.of("", Nivel.INFO));
        private final Map<String, List<Saida>> saidas = new HashMap<>();
        private int falhas;

        LoggerFactory(LongSupplier relogio) {
            this.relogio = Objects.requireNonNull(relogio);
        }

        Logger getLogger(String nome) {
            Objects.requireNonNull(nome, "nome");
            return loggers.computeIfAbsent(nome, n -> new Logger(n, this));
        }

        void definirNivel(String nome, Nivel nivel) {
            niveis.put(Objects.requireNonNull(nome), Objects.requireNonNull(nivel));
        }

        void adicionarAppender(String nome, Appender appender, Formatador formatador, Nivel minimo) {
            saidas.computeIfAbsent(Objects.requireNonNull(nome), n -> new ArrayList<>())
                    .add(new Saida(Objects.requireNonNull(appender), Objects.requireNonNull(formatador), Objects.requireNonNull(minimo)));
        }

        int falhasDeAppender() {
            return falhas;
        }

        // O(profundidade do nome). Em produção, o Logback guarda esse valor em cache no próprio logger.
        Nivel nivelEfetivo(String nome) {
            for (String n = nome; ; n = pai(n)) {
                Nivel nivel = niveis.get(n);
                if (nivel != null) return nivel; // a raiz "" sempre tem nível
            }
        }

        void publicar(String nome, Nivel nivel, String mensagem) {
            Evento evento = new Evento(relogio.getAsLong(), nivel, nome, mensagem);
            for (String n = nome; ; n = pai(n)) {
                for (Saida s : saidas.getOrDefault(n, List.of())) {
                    if (nivel.compareTo(s.minimo()) < 0) continue;
                    try {
                        s.appender().escrever(s.formatador().formatar(evento));
                    } catch (RuntimeException e) {
                        falhas++; // logging nunca derruba a aplicação
                    }
                }
                if (n.isEmpty()) return;
            }
        }

        static String pai(String nome) {
            int i = nome.lastIndexOf('.');
            return i < 0 ? "" : nome.substring(0, i);
        }
    }

    static class Logger {
        private final String nome;
        private final LoggerFactory fabrica;

        private Logger(String nome, LoggerFactory fabrica) {
            this.nome = nome;
            this.fabrica = fabrica;
        }

        boolean isEnabled(Nivel nivel) {
            return nivel.compareTo(fabrica.nivelEfetivo(nome)) >= 0;
        }

        void debug(String msg, Object... args) { log(Nivel.DEBUG, msg, args); }
        void info(String msg, Object... args) { log(Nivel.INFO, msg, args); }
        void warn(String msg, Object... args) { log(Nivel.WARN, msg, args); }
        void error(String msg, Object... args) { log(Nivel.ERROR, msg, args); }

        private void log(Nivel nivel, String msg, Object... args) {
            if (!isEnabled(nivel)) return; // antes de formatar: nenhum toString é chamado
            fabrica.publicar(nome, nivel, formatar(msg, args));
        }

        // O(tamanho da mensagem)
        static String formatar(String msg, Object... args) {
            if (args == null || args.length == 0) return msg;
            StringBuilder sb = new StringBuilder(msg.length() + 16 * args.length);
            int arg = 0, i = 0;
            while (i < msg.length()) {
                if (arg < args.length && msg.startsWith("{}", i)) {
                    sb.append(String.valueOf(args[arg++]));
                    i += 2;
                } else {
                    sb.append(msg.charAt(i++));
                }
            }
            return sb.toString();
        }
    }
}

