import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;

class SolutionTest {
    final long[] agora = {0};
    final Solution.LoggerFactory f = new Solution.LoggerFactory(() -> agora[0]);
    final Solution.MemoriaAppender raiz = new Solution.MemoriaAppender();
    final Solution.Formatador padrao = new Solution.FormatadorPadrao();

    void comAppenderNaRaiz() {
        f.adicionarAppender("", raiz, padrao, Solution.Nivel.DEBUG);
    }

    @Test void raizComecaEmInfo() {
        comAppenderNaRaiz();
        var log = f.getLogger("app");
        log.debug("escondido");
        log.info("ola");
        agora[0] = 42;
        log.error("falhou");
        assertEquals(List.of("0 INFO [app] ola", "42 ERROR [app] falhou"), raiz.linhas());
    }

    @Test void mesmaInstanciaPorNome() {
        assertSame(f.getLogger("app.x"), f.getLogger("app.x"));
    }

    @Test void placeholders() {
        comAppenderNaRaiz();
        var log = f.getLogger("app");
        log.info("pedido {} de {}", 42, "ana");
        log.info("faltou {} e {}", 1);
        log.info("sobrou {}", 1, 2);
        log.info("sem args {}");
        log.info("nulo {}", (Object) null);
        assertEquals(List.of(
                "0 INFO [app] pedido 42 de ana",
                "0 INFO [app] faltou 1 e {}",
                "0 INFO [app] sobrou 1",
                "0 INFO [app] sem args {}",
                "0 INFO [app] nulo null"), raiz.linhas());
    }

    @Test void naoFormataQuandoDesligado() {
        comAppenderNaRaiz();
        int[] chamadas = {0};
        Object caro = new Object() {
            @Override public String toString() { chamadas[0]++; return "caro"; }
        };
        var log = f.getLogger("app");
        log.debug("valor {}", caro);
        assertEquals(0, chamadas[0]);
        log.info("valor {}", caro);
        assertEquals(1, chamadas[0]);
    }

    @Test void nivelHerdadoPorSegmentoDePonto() {
        f.definirNivel("app", Solution.Nivel.DEBUG);
        assertTrue(f.getLogger("app").isEnabled(Solution.Nivel.DEBUG));
        assertTrue(f.getLogger("app.pagamentos.pix").isEnabled(Solution.Nivel.DEBUG));
        assertFalse(f.getLogger("application").isEnabled(Solution.Nivel.DEBUG));
        assertFalse(f.getLogger("outro").isEnabled(Solution.Nivel.DEBUG));
    }

    @Test void nivelMaisEspecificoVence() {
        f.definirNivel("app", Solution.Nivel.DEBUG);
        f.definirNivel("app.ruidoso", Solution.Nivel.ERROR);
        var log = f.getLogger("app.ruidoso.cliente");
        assertFalse(log.isEnabled(Solution.Nivel.WARN));
        assertTrue(log.isEnabled(Solution.Nivel.ERROR));
        assertTrue(f.getLogger("app.calmo").isEnabled(Solution.Nivel.DEBUG));
    }

    @Test void mudancaDeNivelValeParaLoggerJaCriado() {
        var log = f.getLogger("app");
        assertFalse(log.isEnabled(Solution.Nivel.DEBUG));
        f.definirNivel("", Solution.Nivel.DEBUG);
        assertTrue(log.isEnabled(Solution.Nivel.DEBUG));
    }

    @Test void appendersDosAncestraisRecebemEmOrdem() {
        var linhas = new java.util.ArrayList<String>();
        f.adicionarAppender("", l -> linhas.add("raiz: " + l), padrao, Solution.Nivel.DEBUG);
        f.adicionarAppender("app.pagamentos", l -> linhas.add("pag: " + l), padrao, Solution.Nivel.DEBUG);
        f.getLogger("app.pagamentos.pix").info("pix ok");
        f.getLogger("app.outro").info("outro");
        assertEquals(List.of(
                "pag: 0 INFO [app.pagamentos.pix] pix ok",
                "raiz: 0 INFO [app.pagamentos.pix] pix ok",
                "raiz: 0 INFO [app.outro] outro"), linhas);
    }

    @Test void mesmoAppenderNoPaiENoFilhoDuplicaALinha() {
        comAppenderNaRaiz();
        f.adicionarAppender("app", raiz, padrao, Solution.Nivel.DEBUG);
        f.getLogger("app").info("x");
        assertEquals(2, raiz.linhas().size());
    }

    @Test void nivelMinimoDoAppender() {
        var alertas = new Solution.MemoriaAppender();
        f.adicionarAppender("", alertas, padrao, Solution.Nivel.WARN);
        var log = f.getLogger("app");
        log.info("info");
        log.warn("warn");
        log.error("error");
        assertEquals(List.of("0 WARN [app] warn", "0 ERROR [app] error"), alertas.linhas());
    }

    @Test void appenderQueFalhaNaoAfetaOsOutros() {
        f.adicionarAppender("", l -> { throw new IllegalStateException("disco cheio"); }, padrao, Solution.Nivel.DEBUG);
        f.adicionarAppender("", raiz, padrao, Solution.Nivel.DEBUG);
        f.adicionarAppender("", raiz, e -> { throw new RuntimeException("formatador quebrado"); }, Solution.Nivel.DEBUG);
        assertDoesNotThrow(() -> f.getLogger("app").info("segue"));
        assertEquals(List.of("0 INFO [app] segue"), raiz.linhas());
        assertEquals(2, f.falhasDeAppender());
    }

    @Test void formatadorPlugavel() {
        Solution.Formatador json = e -> "{\"nivel\":\"" + e.nivel() + "\",\"msg\":\"" + e.mensagem() + "\"}";
        f.adicionarAppender("", raiz, json, Solution.Nivel.DEBUG);
        f.getLogger("app").warn("lento {}ms", 350);
        assertEquals(List.of("{\"nivel\":\"WARN\",\"msg\":\"lento 350ms\"}"), raiz.linhas());
    }

    @Test void loggerRaiz() {
        comAppenderNaRaiz();
        f.getLogger("").info("boot");
        assertEquals(List.of("0 INFO [] boot"), raiz.linhas());
    }
}
